describe("toSlug", () => {
  it("slugifies Latin names", () => {
    expect(toSlug("To Do")).toBe("to-do");
    expect(toSlug("  In Progress!  ")).toBe("in-progress");
  });

  it("keeps non-Latin scripts instead of producing an empty slug", () => {
